package com.scholarshipmatcher.controller;
import com.scholarshipmatcher.entity.*;import com.scholarshipmatcher.repository.*;import com.scholarshipmatcher.service.MatchingService;import jakarta.servlet.http.HttpSession;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;import java.time.Instant;import java.util.*;
import org.springframework.security.web.csrf.CsrfToken;
@RestController @RequestMapping("/api") public class ApiController {
 private final UserRepository users;private final ProfileRepository profiles;private final ScholarshipRepository scholarships;private final SavedRepository saved;private final ApplicationRepository applications;private final MatchCheckRepository checks;private final PasswordEncoder encoder;private final MatchingService matcher;
 public ApiController(UserRepository u,ProfileRepository p,ScholarshipRepository s,SavedRepository sv,ApplicationRepository a,MatchCheckRepository checks,PasswordEncoder e,MatchingService m){users=u;profiles=p;scholarships=s;saved=sv;applications=a;this.checks=checks;encoder=e;matcher=m;}
 public record Register(@NotBlank @Size(max=120) String name,@Email @NotBlank @Size(max=190) String email,@NotBlank @Size(min=8,max=100) String password){} public record Login(@Email @NotBlank @Size(max=190) String email,@NotBlank String password){}
 @GetMapping("/auth/csrf") public Object csrf(CsrfToken token){return Map.of("token",token.getToken());}
 @PostMapping("/auth/register") public Object register(@Valid @RequestBody Register r,HttpSession session,HttpServletRequest request){if(users.findByEmailIgnoreCase(r.email()).isPresent())throw new IllegalArgumentException("An account with this email already exists");var u=users.save(new UserAccount(r.name().trim(),r.email().trim().toLowerCase(),encoder.encode(r.password())));request.changeSessionId();session.setAttribute("userId",u.id);return Map.of("id",u.id,"name",u.fullName,"email",u.email);}
 @PostMapping("/auth/login") public Object login(@Valid @RequestBody Login r,HttpSession s,HttpServletRequest request){var u=users.findByEmailIgnoreCase(r.email()).orElseThrow(()->new IllegalArgumentException("Email or password is incorrect"));if(!encoder.matches(r.password(),u.passwordHash))throw new IllegalArgumentException("Email or password is incorrect");request.changeSessionId();s.setAttribute("userId",u.id);return Map.of("id",u.id,"name",u.fullName,"email",u.email);}
 @PostMapping("/auth/logout") public Object logout(HttpSession s){s.invalidate();return Map.of("ok",true);}
 @GetMapping("/auth/me") public Object me(HttpSession s){var u=user(s);return Map.of("id",u.id,"name",u.fullName,"email",u.email);}
 @GetMapping("/scholarships") public Object list(){return scholarships.findAll();}
 @GetMapping("/scholarships/{id}") public Object detail(@PathVariable Long id){return scholarships.findById(id).orElseThrow(()->new NoSuchElementException("Scholarship not found"));}
 @PostMapping("/match") public Object match(@RequestBody Map<String,Object> profile){return matcher.match(profile);}
 @GetMapping("/checks") public Object checks(HttpSession s){return checks.findByUserIdOrderByCheckedAtDesc(user(s).id).stream().map(c->Map.of("id",c.id,"studentName",c.studentName,"potentialMatches",c.potentialMatches,"needsReview",c.needsReview,"notEligible",c.notEligible,"checkedAt",c.checkedAt.toString())).toList();}
 @PostMapping("/checks") public Object saveCheck(HttpSession s,@RequestBody Map<String,Object> data){var u=user(s);String name=Optional.ofNullable(data.get("studentName")).map(Object::toString).filter(v->!v.isBlank()).orElse(u.fullName);int potential=count(data,"potentialMatches"),review=count(data,"needsReview"),not=count(data,"notEligible");var c=checks.save(new MatchCheck(u,name,potential,review,not));return Map.of("id",c.id,"studentName",c.studentName,"potentialMatches",c.potentialMatches,"needsReview",c.needsReview,"notEligible",c.notEligible,"checkedAt",c.checkedAt.toString());}
 private int count(Map<String,Object> data,String key){try{int v=Integer.parseInt(String.valueOf(data.getOrDefault(key,0)));if(v<0||v>10000)throw new NumberFormatException();return v;}catch(Exception ex){throw new IllegalArgumentException("Invalid match count");}}
 @GetMapping("/profile") public Object profile(HttpSession s){var p=profiles.findById(user(s).id).orElse(null);return p==null?null:profileData(p);}
 @PutMapping("/profile") public Object putProfile(HttpSession s,@Valid @RequestBody StudentProfile input){var u=user(s);var p=profiles.findById(u.id).orElseGet(StudentProfile::new);p.user=u;p.studentName=input.studentName;p.state=input.state;p.category=input.category;p.gender=input.gender;p.educationLevel=input.educationLevel;p.course=input.course;p.academicYear=input.academicYear;p.marks=input.marks;p.familyIncome=input.familyIncome;return profileData(profiles.save(p));}
 private Map<String,Object> profileData(StudentProfile p){var m=new LinkedHashMap<String,Object>();m.put("studentName",p.studentName);m.put("state",p.state);m.put("category",p.category);m.put("gender",p.gender);m.put("educationLevel",p.educationLevel);m.put("course",p.course);m.put("academicYear",p.academicYear);m.put("marks",p.marks);m.put("familyIncome",p.familyIncome);return m;}
 @GetMapping("/saved") public Object saved(HttpSession s){return saved.findByUserId(user(s).id).stream().map(x->x.scholarship).toList();}
 @PostMapping("/saved/{id}") public Object addSaved(HttpSession s,@PathVariable Long id){var u=user(s);var sch=scholarships.findById(id).orElseThrow();if(saved.findByUserIdAndScholarshipId(u.id,id).isEmpty())saved.save(new SavedScholarship(u,sch));return Map.of("ok",true);}
 @DeleteMapping("/saved/{id}") public Object deleteSaved(HttpSession s,@PathVariable Long id){saved.findByUserIdAndScholarshipId(user(s).id,id).ifPresent(saved::delete);return Map.of("ok",true);}
 @GetMapping("/applications") public Object applications(HttpSession s){return applications.findByUserId(user(s).id).stream().map(this::applicationData).toList();}
 @PostMapping("/applications/{id}") public Object track(HttpSession s,@PathVariable Long id,@RequestBody Map<String,String> data){var u=user(s);var a=applications.findByUserId(u.id).stream().filter(x->x.scholarship.id.equals(id)).findFirst().orElseGet(()->new ScholarshipApplication(u,scholarships.findById(id).orElseThrow(),"Planning"));a.status=Optional.ofNullable(data.get("status")).filter(v->Set.of("Planning","Preparing","Submitted","Awarded","Rejected").contains(v)).orElse("Planning");a.updatedAt=Instant.now();return applicationData(applications.save(a));}
 private Map<String,Object> applicationData(ScholarshipApplication a){return Map.of("id",a.id,"scholarship",Map.of("id",a.scholarship.id,"name",a.scholarship.name),"status",a.status,"updatedAt",a.updatedAt.toString());}
 private UserAccount user(HttpSession s){Object id=s.getAttribute("userId");if(id==null)throw new org.springframework.security.access.AccessDeniedException("Login required");return users.findById((Long)id).orElseThrow();}
 @ExceptionHandler(IllegalArgumentException.class) public ResponseEntity<?> badInput(Exception e){return ResponseEntity.badRequest().body(Map.of("error",e.getMessage()));}
 @ExceptionHandler(NoSuchElementException.class) public ResponseEntity<?> notFound(Exception e){return ResponseEntity.status(404).body(Map.of("error",e.getMessage()));}
}
